 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();torch.set_num_threads(1);torch.cuda.set_per_process_memory_fraction(1*2**30/torch.cuda.get_device_properties(0).total_memory);torch.manual_seed(348);device='cuda';r=torch.randn(2,8,dtype=torch.float64,device=device);v=torch.rand(2,8,dtype=r.dtype,device=device)+1;m=torch.randn(2,8,3,dtype=r.dtype,device=device);beta=2.;actual=covariance_log_ratio(r,v,m,beta);base=torch.diag_embed(v);alt=base+beta*m@m.transpose(-1,-2);direct=.5*(torch.linalg.slogdet(base).logabsdet-torch.linalg.slogdet(alt).logabsdet+(r[...,None]*(torch.linalg.solve(base,r[...,None])-torch.linalg.solve(alt,r[...,None]))).sum((-2,-1)));error=float((actual-direct).abs().max());assert error<1e-9;assert torch.equal(covariance_log_ratio(r,v,m,0),torch.zeros(2,dtype=r.dtype,device=device))
 x=torch.randn(336,3,dtype=torch.float64,device=device);g=torch.zeros(3,3,dtype=x.dtype,device=device);g[0,1]=g[1,2]=1;s=condition(x[:256],g);mu=innovations(x,s)[3];changed=x.clone();changed[326,1]+=100;mu2=innovations(changed,s)[3];assert mu[326-8,1]==mu2[326-8,1];prior=SyndromePrior().cuda();initial=parameter_sha(prior);out=evidence(x,g,state=s);base=prior(out['log_factors']);future=x.clone();future[330:]+=100;other=prior(evidence(future,g)['log_factors']);assert torch.equal(base['logit'][:10],other['logit'][:10]);perm=torch.tensor([2,0,1],device=device);pout=prior(evidence(x[:,perm],g[perm][:,perm])['log_factors']);perror=float((base['logit']-pout['logit']).abs().max());rerror=float((base['root'][:,perm]-pout['root']).abs().max());assert max(perror,rerror)<1e-6;assert torch.allclose(base['root'].sum(-1),torch.ones(16,dtype=x.dtype,device=device));assert parameter_sha(prior)==initial
