 big=torch.randn(336,20,dtype=x.dtype,device=device);bg=torch.zeros(20,20,dtype=x.dtype,device=device);bg[torch.arange(19),torch.arange(1,20)]=1;large=evidence(big,bg);assert torch.isfinite(large['log_factors']).all()
